        self.assertEqual(order_total([(10.0, 20), (10.0, 20)]), 401.76)

    def test_bulk_discount_does_not_apply_below_40_items(self):
        self.assertEqual(order_total([(10.0, 39)]), 421.2)


if __name__ == "__main__":
    unittest.main()
